begin;
create extension if not exists pgtap with schema extensions;
select plan(22);
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('returns','return_lines','refunds','return_settings') and c.relrowsecurity),4::bigint,'all return tables enable RLS');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_roles r on r.oid=c.relowner where n.nspname='public' and c.relname in ('returns','return_lines','refunds','return_settings') and r.rolname='returns_writer'),4::bigint,'dedicated writer owns tables');
select ok((select not rolcanlogin and not rolbypassrls from pg_roles where rolname='returns_writer'),'writer cannot log in or bypass other RLS');
select ok(not pg_has_role('service_role','returns_writer','MEMBER'),'service cannot become writer');
select ok(not has_schema_privilege('anon','returns_private','USAGE'),'anon cannot call returns RPC');
select ok(not has_schema_privilege('authenticated','returns_private','USAGE'),'authenticated cannot call returns RPC');
select ok(not has_table_privilege('anon','public.returns','SELECT'),'anon cannot read returns');
select ok(not has_table_privilege('authenticated','public.returns','SELECT'),'authenticated cannot read returns');
select ok(not has_table_privilege('anon','public.return_lines','SELECT'),'anon cannot read lines');
select ok(not has_table_privilege('authenticated','public.return_lines','SELECT'),'authenticated cannot read lines');
select ok(not has_table_privilege('anon','public.refunds','SELECT'),'anon cannot read refunds');
select ok(not has_table_privilege('authenticated','public.refunds','SELECT'),'authenticated cannot read refunds');
select ok(not has_table_privilege('authenticated','public.return_settings','SELECT'),'policy remains private');
select ok(not has_table_privilege('service_role','public.returns','INSERT'),'service cannot bypass acceptance');
select ok(not has_table_privilege('service_role','public.return_lines','UPDATE'),'service cannot inflate quantities');
select ok(not has_table_privilege('service_role','public.refunds','UPDATE'),'service cannot fabricate settlement');
select ok(not has_table_privilege('service_role','public.refunds','DELETE'),'service cannot erase ceiling commitments');
select ok(not has_table_privilege('returns_writer','public.inventory_balances','UPDATE'),'returns writer cannot overwrite inventory');
select ok(has_function_privilege('service_role','returns_private.accept_return(uuid,uuid,uuid,text,text,jsonb)','EXECUTE'),'service can invoke atomic return');
select ok(has_function_privilege('service_role','returns_private.settle_manual_refund(uuid,uuid,uuid,text,text)','EXECUTE'),'service can invoke sanctioned manual settlement');
select is((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='returns_private' and p.proname<>'forbid_history_mutation' and (not p.prosecdef or not p.proconfig @> array['search_path=""'])),0::bigint,'all entrypoints are hardened definers');
select is((select count(*) from public.return_settings where enabled),0::bigint,'no production tenant enabled by migration');
select * from finish();
rollback;
